4756	  //------------------------------------------------------------
4757	  // Parser event handlers.  Clang will call them to notify this
4758	  // ASTConsumer as it parses the source code.  See class ASTConsumer in
4759	  // clang/AST/ASTConsumer.h
4760	  // for all the handlers we can override.
4761	
4762	  // Called once at the beginning of the compilation.
4763	  void Initialize(ASTContext& context) override {}  // NOLINT
4764	
4765	  // Called once at the end of the compilation.
4766	  void HandleTranslationUnit(ASTContext& context) override {  // NOLINT
4767	    // TODO(csilvers): automatically detect preprocessing is done, somehow.
4768	    const_cast<IwyuPreprocessorInfo*>(&preprocessor_info())->
4769	        HandlePreprocessingDone();
4770	
4771	    TranslationUnitDecl* tu_decl = context.getTranslationUnitDecl();
4772	
4773	    // Sema::TUScope is reset after parsing, but Sema::getCurScope still points
4774	    // to the translation unit decl scope. TUScope is required for lookup in
4775	    // some complex scenarios, so re-wire it before running IWYU AST passes.
4776	    // Assert their expected state so we notice if these assumptions change.
4777	    Sema& sema = compiler()->getSema();
4778	    CHECK_(sema.TUScope == nullptr);
4779	    CHECK_(sema.getCurScope() != nullptr);
4780	    sema.TUScope = sema.getCurScope();
4781	
4782	    // We run a separate pass to force parsing of late-parsed function
4783	    // templates.
4784	    ParseFunctionTemplates(sema, tu_decl);
4785	
4786	    // Clang lazily constructs the implicit methods of a C++ class (the
4787	    // default constructor and destructor, etc) -- it only bothers to
4788	    // create a CXXMethodDecl if someone actually calls these classes.
4789	    // But we need to be non-lazy: IWYU depends on analyzing what future
4790	    // code *may* call in a class, not what current code *does*.  So we
4791	    // force all the lazy evaluation to happen here.
4792	    InstantiateImplicitMethods(sema, tu_decl);
4793	
4794	    // Run IWYU analysis.
4795	    TraverseDecl(tu_decl);
4796	
4797	    // Check if any unrecoverable errors have occurred.
4798	    // There is no point in continuing when the AST is in a bad state.
4799	    if (compiler()->getDiagnostics().hasUnrecoverableErrorOccurred())
4800	      exit(EXIT_FAILURE);
4801	
4802	    const set<OptionalFileEntryRef>* const files_to_report_iwyu_violations_for =
4803	        preprocessor_info().files_to_report_iwyu_violations_for();
4804	
4805	    // Some analysis, such as UsingDecl resolution, is deferred until the
4806	    // entire AST is visited because it's only at that point that we know if
4807	    // the symbol was actually used or not.
4808	    // We perform that analysis here before CalculateAndReportIwyuViolations.
4809	    for (OptionalFileEntryRef file : *files_to_report_iwyu_violations_for) {
4810	      CHECK_(preprocessor_info().FileInfoFor(file));
4811	      preprocessor_info().FileInfoFor(file)->ResolvePendingAnalysis();
4812	    }
4813	
4814	    // We have to calculate the .h files before the .cc file, since
4815	    // the .cc file inherits #includes from the .h files, and we
4816	    // need to figure out what those #includes are going to be.
4817	    size_t num_edits = 0;
4818	    OptionalFileEntryRef const main_file = preprocessor_info().main_file();
4819	    for (OptionalFileEntryRef file : *files_to_report_iwyu_violations_for) {
4820	      if (file == main_file)
4821	        continue;
4822	      CHECK_(preprocessor_info().FileInfoFor(file));
4823	      num_edits += preprocessor_info().FileInfoFor(file)
4824	          ->CalculateAndReportIwyuViolations();
4825	    }
4826	    CHECK_(preprocessor_info().FileInfoFor(main_file));
4827	    num_edits += preprocessor_info().FileInfoFor(main_file)
4828	        ->CalculateAndReportIwyuViolations();
4829	
4830	    int exit_code = EXIT_SUCCESS;
4831	    if (GlobalFlags().exit_code_always) {
4832	      // If we should always fail, use --error_always value.
4833	      exit_code = GlobalFlags().exit_code_always;
4834	    } else if (num_edits > 0) {
4835	      // If there were IWYU violations, use --error value.
4836	      exit_code = GlobalFlags().exit_code_error;
4837	    }
4838	
4839	    exit(exit_code);
4840	  }
