4842	  void ParseFunctionTemplates(Sema& sema, TranslationUnitDecl* tu_decl) {
4843	    set<FunctionDecl*> late_parsed_decls = GetLateParsedFunctionDecls(tu_decl);
4844	
4845	    // If we have any late-parsed functions, make sure the
4846	    // -fdelayed-template-parsing flag is on. Otherwise we don't know where
4847	    // they came from.
4848	    CHECK_((compiler()->getLangOpts().DelayedTemplateParsing ||
4849	            late_parsed_decls.empty()) &&
4850	           "Should not have late-parsed decls without "
4851	           "-fdelayed-template-parsing.");
4852	
4853	    for (const FunctionDecl* fd : late_parsed_decls) {
4854	      CHECK_(fd->isLateTemplateParsed());
4855	
4856	      if (CanIgnoreLocation(GetLocation(fd)))
4857	        continue;
4858	
4859	      // Force parsing and AST building of the yet-uninstantiated function
4860	      // template body.
4861	      LateParsedTemplate* lpt = sema.LateParsedTemplateMap[fd].get();
4862	      sema.LateTemplateParser(sema.OpaqueParser, *lpt);
4863	    }
4864	  }
