4945	  bool VisitUsingDecl(UsingDecl* decl) {
4946	    // The shadow decls hold the declarations for the var/fn/etc we're
4947	    // using.  (There may be more than one if, say, we're using an
4948	    // overloaded function.)  We don't want to add all of them at once
4949	    // though, because that will drag in every overload even if we're
4950	    // only using one.  Instead, we keep track of the using decl and
4951	    // mark it as touched when something actually uses it.
4952	    preprocessor_info().FileInfoFor(CurrentFileEntry())->AddUsingDecl(decl);
4953	
4954	    if (CanIgnoreCurrentASTNode())
4955	      return true;
4956	    return Base::VisitUsingDecl(decl);
4957	  }
