5249	  bool VisitDeclRefExpr(DeclRefExpr* expr) {
5250	    if (CanIgnoreCurrentASTNode())
5251	      return true;
5252	    // Special case for UsingShadowDecl to track UsingDecls correctly. The
5253	    // actual decl will be reported by obtaining it from the UsingShadowDecl
5254	    // once we've tracked the UsingDecl use.
5255	    // Called functions are handled in TraverseCallExpr, but not
5256	    // using-declarations introducing them.
5257	    if (const UsingShadowDecl* found_decl = DynCastFrom(expr->getFoundDecl())) {
5258	      ReportDeclUse(
5259	          CurrentLoc(), found_decl, nullptr, 0,
5260	          /*report_using_decl_only=*/IsCallExprFunRef(current_ast_node()));
