4866	  void InstantiateImplicitMethods(Sema& sema, TranslationUnitDecl* tu_decl) {
4867	    // Collect all implicit ctors/dtors that need to be instantiated.
4868	    struct Visitor : public RecursiveASTVisitor<Visitor> {
4869	      Visitor(Sema& sema) : sema(sema) {
4870	      }
4871	
4872	      bool VisitCXXRecordDecl(CXXRecordDecl* decl) {
4873	        if (CanIgnoreLocation(GetLocation(decl)))
4874	          return true;
4875	
4876	        if (!decl->getDefinition() || decl->isDependentContext() ||
4877	            decl->isBeingDefined()) {
4878	          return true;
4879	        }
4880	
4881	        if (CXXConstructorDecl* ctor = sema.LookupDefaultConstructor(decl)) {
4882	          may_need_definition.insert(ctor);
4883	        } else if (CXXDestructorDecl* dtor = sema.LookupDestructor(decl)) {
4884	          may_need_definition.insert(dtor);
4885	        }
4886	
4887	        return true;
4888	      }
4889	
4890	      Sema& sema;
4891	      std::set<CXXMethodDecl*> may_need_definition;
4892	    };
4893	
4894	    // Run visitor to collect implicit methods.
4895	    Visitor v(sema);
4896	    v.TraverseDecl(tu_decl);
4897	
4898	    // For each method collected, let Sema define them.
4899	    for (CXXMethodDecl* method : v.may_need_definition) {
4900	      if (!method->isDefaulted() || method->isDeleted() || method->hasBody())
4901	        continue;
4902	
4903	      SourceLocation loc = GetLocation(method->getParent());
4904	      if (auto* ctor = dyn_cast<CXXConstructorDecl>(method)) {
4905	        sema.DefineImplicitDefaultConstructor(loc, ctor);
4906	      } else if (auto* dtor = dyn_cast<CXXDestructorDecl>(method)) {
4907	        sema.DefineImplicitDestructor(loc, dtor);
4908	      }
4909	    }
4910	
4911	    // Clang queues up method instantiations. Process them now.
4912	    sema.PerformPendingInstantiations();
4913	  }
