4959	  bool VisitTagDecl(TagDecl* decl) {
4960	    if (CanIgnoreCurrentASTNode())
4961	      return true;
4962	
4963	    // Skip the injected class name.
4964	    if (decl->isImplicit())
4965	      return Base::VisitTagDecl(decl);
4966	
4967	    if (IsForwardDecl(decl)) {
4968	      // If we're a templated class, make sure we add the whole template.
4969	      const NamedDecl* decl_to_fwd_declare = decl;
4970	      if (const CXXRecordDecl* cxx_decl = DynCastFrom(decl))
4971	        if (cxx_decl->getDescribedClassTemplate())
4972	          decl_to_fwd_declare = cxx_decl->getDescribedClassTemplate();
4973	
4974	      // We've found a forward-declaration.  We'll report we've found
4975	      // it, but we also want to report if we know already that we
4976	      // should keep this forward-declaration around (and not consider
4977	      // it for deletion if it's never used).  There are a few
4978	      // situations we can do this, described below.
4979	      bool definitely_keep_fwd_decl = false;
4980	
4981	      // (1) If the forward-decl has a linkage spec ('extern "C"')
4982	      // then it can't be removed, since that information probably
4983	      // isn't encoded anywhere else.
4984	      // (Surprisingly classes can have linkage specs! -- they are
4985	      // applied to all static methods of the class.  See
4986	      // http://msdn.microsoft.com/en-us/library/ms882260.aspx.)
4987	      if (current_ast_node()->ParentIsA<LinkageSpecDecl>()) {
4988	        definitely_keep_fwd_decl = true;
4989	
4990	      // (2) GCC-style __attributes__ work the same way: we can't assume
4991	      // that attributes are consistent between declarations, so we can't
4992	      // remove a decl with attributes unless they're inherited, i.e. propagated
4993	      // from another redeclaration as opposed to explicitly written.
4994	      } else if (decl->hasAttrs()) {
4995	        for (const Attr* attr : decl->getAttrs()) {
4996	          if (!attr->isInherited()) {
4997	            definitely_keep_fwd_decl = true;
4998	            break;
4999	          }
5000	        }
5001	
5002	      // (3) If we're a nested class ("class A { class SubA; };"),
5003	      // then we can't necessary be removed either, since we're part
5004	      // of the public API of the enclosing class -- it's illegal to
5005	      // have a nested class and not at least declare it in the
5006	      // enclosing class.  If the nested class is actually defined in
5007	      // the enclosing class, then we're fine; if not, we need to keep
5008	      // the first forward-declaration.
5009	      } else if (IsNestedTagAsWritten(current_ast_node())) {
5010	        if (!decl->getDefinition() || decl->getDefinition()->isOutOfLine()) {
5011	          // TODO(kimgr): Member class redeclarations are illegal, per C++
5012	          // standard DR85, so this check for first redecl can be removed.
5013	          // Nested classes should always be definitely kept. More details here:
5014	          // http://comments.gmane.org/gmane.comp.compilers.clang.scm/74782
5015	          // GCC and MSVC both still allow redeclarations of nested classes,
5016	          // though, so it seems hygienic to remove all but one.
5017	          if (const NamedDecl* first_decl = GetFirstRedecl(decl)) {
5018	            // Check if we're the decl with the smallest line number.
5019	            if (decl == first_decl)
5020	              definitely_keep_fwd_decl = true;
5021	          }
5022	        }
5023	      } else if (preprocessor_info().ForwardDeclareIsMarkedKeep(decl)) {
5024	        definitely_keep_fwd_decl = true;
5025	      } else if (preprocessor_info().ForwardDeclareIsExported(decl)) {
5026	        definitely_keep_fwd_decl = true;
5027	      }
5028	
5029	      preprocessor_info().FileInfoFor(CurrentFileEntry())->AddForwardDeclare(
5030	          decl_to_fwd_declare, definitely_keep_fwd_decl);
5031	    }
5032	    return Base::VisitTagDecl(decl);
5033	  }
