bool IsDefTplArgSpecified(const NamedDecl* tpl_param) {
  if (const auto* type_param = dyn_cast<TemplateTypeParmDecl>(tpl_param)) {
    return type_param->hasDefaultArgument() &&
           !type_param->defaultArgumentWasInherited();
  }
  if (const auto* nttp = dyn_cast<NonTypeTemplateParmDecl>(tpl_param))
    return nttp->hasDefaultArgument() && !nttp->defaultArgumentWasInherited();
  if (const auto* tpl_tpl_param =
          dyn_cast<TemplateTemplateParmDecl>(tpl_param)) {
    return tpl_tpl_param->hasDefaultArgument() &&
           !tpl_tpl_param->defaultArgumentWasInherited();
  }
  CHECK_UNREACHABLE_("Not a template parameter");
}

FunctionDecl* GetRedeclSpecifyingDefArg(unsigned i, FunctionDecl* func) {
  if (func->isFunctionTemplateSpecialization())
    return func;
  for (FunctionDecl* redecl : func->redecls()) {
    if (IsDefArgSpecified(i, redecl))
      return redecl;
  }
  CHECK_UNREACHABLE_("There should be a redecl specifying the default arg");
}

const TemplateDecl* GetRedeclSpecifyingDefArg(unsigned i,
                                              const TemplateDecl* decl) {
  const auto* redeclarable = dyn_cast<RedeclarableTemplateDecl>(decl);
  // If this template isn't redeclarable, then the given declaration should
  // specify default arguments, if any.
  if (!redeclarable)
    return decl;
  for (const RedeclarableTemplateDecl* redecl : redeclarable->redecls()) {
    const TemplateParameterList* params = redecl->getTemplateParameters();
    if (IsDefTplArgSpecified(params->getParam(i)))
      return redecl;
  }
  CHECK_UNREACHABLE_("There should be a redecl specifying the default arg");
}

const NamedDecl* GetIndependentRedecl(const NamedDecl* decl) {
  const auto* redeclarable = dyn_cast<RedeclarableTemplateDecl>(decl);
  if (!redeclarable)
    return decl;
  if (const TemplateDecl* found = GetRedeclNotSpecifyingAnyDefArg(redeclarable))
    return found;
  // If there is no redeclaration without any explicitly written default
  // arguments, return the one specifying the last argument because it doesn't
  // depend on any other redeclaration.
  unsigned last_param_idx = GetTplParamNumberWithoutPack(redeclarable) - 1;
  return GetRedeclSpecifyingDefArg(last_param_idx, redeclarable);
}

unsigned GetTplParamNumberWithoutPack(const TemplateDecl* tpl) {
  const TemplateParameterList* params = tpl->getTemplateParameters();
  unsigned size = params->size();
  CHECK_(size > 0);
  return params->hasParameterPack() ? size - 1 : size;
}

